S['CH0612CM'] = [{'k': 'map', 'ch': 'Mở đầu', 'cap': ('VÌ SAO TÀU MẸ', 'GHÉ THẲNG CÁI MÉP?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'map': {'kf': [(12.5, 109.5, 5.0, 0.0), (11.0, 107.3, 7.8, 0.5), (10.5, 107.02, 12.4, 1.0)], 'nhan': [(1.29, 103.85, 'Singapore', 0.03), (22.3, 114.17, 'Hồng Kông', 0.06), (16.5, 112.0, 'QĐ. Hoàng Sa (Việt Nam)', 0.08, 'chu'), (8.8, 114.5, 'QĐ. Trường Sa (Việt Nam)', 0.1, 'chu'), (10.535, 107.03, 'Cụm cảng Cái Mép – Thị Vải', 0.75, 'cang')], 'duong': [([(1.29, 103.85), (4.5, 105.6), (8.5, 107.2), (10.38, 107.02)], (239, 68, 68), 0.05, 0.4, '')]}, 'say': 'Nhiều người vẫn nghĩ: tàu mẹ, tức những tàu container khổng lồ chạy thẳng sang Mỹ, không bao giờ ghé Việt Nam, hàng của mình phải đi tàu nhỏ sang Singapore rồi mới lên tàu lớn. Nhưng có một cụm cảng nằm giữa rừng ngập mặn, cách trung tâm thành phố rất xa, hai kỳ liền đứng thứ bảy thế giới về hiệu quả, kỳ gần nhất còn xếp trên cả Singapore. Vậy mà năm nay nó bất ngờ tụt bốn bậc, và người chịu thiệt đầu tiên là tài xế và chủ hàng. Vì sao lại là nơi này, và vì sao lại tụt?'}, {'k': '3d', 'set': 'cafevh', 'light': 'day', 'cam': {'from': [[-27.4, 1.5, 2.3], [-27.7, 0.8, 5.2], 42], 'to': [[-27.6, 1.42, 3.0], [-27.7, 0.8, 5.2], 38]}, 'label': 'QUÁN NƯỚC GẦN CẢNG · 5 GIỜ SÁNG', 'cast': [{'a': 'hung', 'p': [-27.15, 0.15, 5.2], 'act': 'dienthoai', 'ngoi': True, 'expr': 'worried'}, {'a': 'cuong', 'p': [-28.25, 0.15, 5.2], 'act': 'noi', 'ngoi': True, 'expr': 'grin'}], 'cap': ('"CẢNG LỚN PHẢI Ở', 'THÀNH PHỐ LỚN CHỨ?"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Năm giờ sáng, ở quán nước gần cảng, Hùng Xa Lộ, tài xế container mười hai năm, vừa nhận tin nhắn: tàu đến trễ, xe anh phải chờ thêm. Cường Sociu ngồi cạnh cười: cảng lớn thì phải ở thành phố lớn chứ, ai lại xây giữa rừng đước thế này? Hùng không cãi lại. Anh chỉ biết mỗi đêm có những con tàu dài như tòa nhà chọc trời nằm ngang cập bến ở đây. Câu chuyện hôm nay đi tìm câu trả lời cho Cường.'}, {'k': 'map', 'ch': 'Chương 1 – Cảng lớn không nằm trong thành phố', 'cap': ('SÔNG TRONG THÀNH PHỐ', 'KHÔNG ĐỦ SÂU CHO TÀU MẸ'), 'cols': ((255, 255, 255), (239, 68, 68)), 'map': {'kf': [(10.6, 106.88, 9.8, 0.0), (10.58, 106.9, 10.3, 1.0)], 'nhan': [(10.758, 106.79, 'Cảng Cát Lái', 0.05), (10.45, 106.84, 'Rừng ngập mặn Cần Giờ', 0.4, 'chu'), (10.535, 107.03, 'Cái Mép – Thị Vải', 0.6, 'cang'), (10.346, 107.084, 'Vũng Tàu', 0.7)]}, 'say': 'Muốn hiểu, anh chị nhìn bản đồ. Cảng lớn truyền thống của thành phố nằm sâu trong sông, tàu phải đi một quãng dài, vòng vèo, luồng không đủ sâu cho những con tàu lớn nhất. Còn cách đó không xa, sông Thị Vải đổ thẳng ra vịnh Gành Rái, nước sâu, gần biển. Lợi thế ấy có từ tự nhiên. Nhưng tự nhiên chỉ cho một nửa câu trả lời.'}, {'k': 'cards', 'anh': 'ov:container ship||container port aerial', 'cap': ('NHIỀU NGƯỜI TỪNG NGHĨ', 'KHÔNG THỂ'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'cards': [('Có sẵn đối thủ', 'Singapore, Hồng Kông', 'Đã là nơi chuyển tàu'), ('Hãng tàu kén', 'Chỉ ghé nơi đủ hàng', 'Tàu to, chạy vắng là lỗ'), ('Xây trước', 'Cảng có, tàu chưa về', 'Có thời gian vắng tàu')], 'say': 'Hồi đầu, nhiều người cho rằng không thể. Singapore và Hồng Kông đã là nơi chuyển tàu của cả khu vực. Hãng tàu lớn chỉ ghé nơi có đủ hàng, vì một con tàu khổng lồ chạy vắng là lỗ. Và đã có một thời gian, các bến ở đây xây xong mà tàu chưa về nhiều. Vậy điều gì đã đổi?'}, {'k': 'section', 'cap': ('LUỒNG CÁI MÉP – THỊ VẢI', 'SÂU 15,5 MÉT'), 'cols': ((255, 255, 255), (255, 196, 0)), 'section': {'sau': 15.5, 'tang': 3.1, 'nhan_sau': 'SÂU 15,5 M', 'nhan_nha': 'BẰNG KHOẢNG 5 TẦNG NHÀ', 'tau': [('Tàu mẹ trọng tải 160.000 – 200.000 tấn (minh họa)', 14.0, 1.0, (255, 196, 0))], 'ghi': ['Không phụ thuộc thủy triều · Báo SGGP 9/2/2024']}, 'say': 'Nửa còn lại là con người làm. Đầu năm hai nghìn không trăm hai mươi bốn, luồng Cái Mép, Thị Vải được nạo vét xong, sâu mười lăm phẩy năm mét, sâu nhất cả nước, bằng khoảng năm tầng nhà chồng lên nhau. Tàu mẹ trọng tải từ một trăm sáu mươi nghìn đến hai trăm nghìn tấn ra vào an toàn, không phải chờ nước lên.'}, {'k': 'giay', 'cap': ('HƠN 1.414 TỶ NGÂN SÁCH', 'ĐỂ ĐÀO SÂU MỘT CON SÔNG'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'giay': {'tieu_de': 'LUỒNG CÁI MÉP – THỊ VẢI', 'so': 'Báo SGGP 9/2/2024', 'dau': 'ĐÃ XONG', 'dieu': [('Độ sâu sau nạo vét', '15,5 MÉT'), ('Cỡ tàu chạy không chờ thủy triều', '160.000 – 200.000 TẤN'), ('Vốn ngân sách', 'HƠN 1.414 TỶ')]}, 'say': 'Số tiền bỏ ra là hơn một nghìn bốn trăm mười bốn tỷ đồng vốn ngân sách, để đào sâu một con sông. Nghe thì lớn, nhưng anh chị sẽ thấy nó đổi lại được gì.'}, {'k': 'noti', 'ch': 'Chương 2 – Con tàu dài gần bằng Landmark 81', 'cap': ('16.828 CONTAINER', 'TRÊN MỘT CON TÀU'), 'cols': ((255, 255, 255), (255, 196, 0)), 'noti': {'gio': '06:15', 'ngay': 'Thứ Năm 13/3/2025', 'items': [('Tin tức', 'Hàng hải · 13/3/2025', 'Tân Cảng Cái Mép – Thị Vải đón tàu OOCL Bauhinia 166.000 tấn, 16.828 TEU', (255, 196, 0)), ('Zalo', 'Đội xe · 13/3/2025', 'Sáng nay tàu lớn vào, anh em xe đầu kéo trực sớm nhé', (34, 197, 94))]}, 'say': 'Ngày mười ba tháng ba năm ngoái, Hùng nhận tin đội xe gọi trực sớm. Cảng Tân Cảng Cái Mép, Thị Vải đón tàu OOCL Bauhinia, trọng tải một trăm sáu mươi sáu nghìn tấn, chở được mười sáu nghìn tám trăm hai mươi tám container loại hai mươi feet.'}, {'k': 'scale', 'cap': ('DÀI 366,99 MÉT', 'BẰNG 4/5 LANDMARK 81'), 'cols': ((255, 255, 255), (255, 196, 0)), 'scale': {'don_vi': 'm', 'muc': [('Tàu OOCL Bauhinia', 367, 'tau', (255, 196, 0), 'dài 366,99 m'), ('Landmark 81', 461, 'thap', (56, 189, 248), 'cao 461 m'), ('3 sân bóng đá xếp nối', 315, 'thanh', (34, 197, 94), 'khoảng 105 m mỗi sân')]}, 'say': 'Con tàu dài gần ba trăm sáu mươi bảy mét, bằng khoảng bốn phần năm chiều cao tòa Landmark tám mươi mốt. So với sân bóng đá, nó dài hơn ba sân nối nhau.'}, {'k': 'bignum', 'anh': 'ov:container ship||container port aerial', 'cap': ('XẾP NỐI 16.828 CONTAINER', 'DÀI KHOẢNG 102 KM'), 'cols': ((255, 255, 255), (255, 196, 0)), 'value': 102, 'fmt': '{:,.0f}', 'unit': ' KM', 'top': '16.828 TEU X 6,1 MÉT MỖI CONTAINER', 'sub': 'Em tự tính, 1 TEU dài 20 feet = 6,1 m', 'col': (255, 196, 0), 'say': 'Còn số container trên tàu, nếu xếp nối đuôi nhau, dài khoảng một trăm linh hai km, em tự tính theo chiều dài sáu phẩy một mét mỗi container. Chừng ấy hàng hóa rời Việt Nam chỉ trên một con tàu.'}, {'k': 'map', 'cap': ('22 TUYẾN ĐI MỸ', '2 TUYẾN ĐI CHÂU ÂU'), 'cols': ((255, 255, 255), (255, 196, 0)), 'map': {'kf': [(28.0, 123.0, 3.35, 0.0), (28.0, 123.0, 3.2, 1.0)], 'nhan': [(10.535, 107.03, 'Cái Mép', 0.02, 'cang'), (34.0, 241.8, 'Bờ Tây nước Mỹ', 0.35), (51.9, 4.1, 'Châu Âu', 0.6)], 'duong': [([(10.4, 107.05), (18.0, 130.0), (25.0, 160.0), (33.0, 200.0), (34.0, 241.8)], (255, 196, 0), 0.08, 0.45, '22 tuyến đi Mỹ'), ([(10.4, 107.05), (1.2, 104.0), (6.0, 80.0), (12.5, 45.0), (30.0, 32.5), (36.0, 15.0), (36.0, -6.0), (44.0, -9.5), (51.9, 4.1)], (56, 189, 248), 0.4, 0.85, '')], 'dim': 0.2}, 'say': 'Tính đến tháng mười một năm nay, theo báo Người Quan Sát, từ Cái Mép có hai mươi hai tuyến tàu đi Mỹ, hai tuyến đi châu Âu và mười tuyến nội Á. Với các tuyến này, hàng của mình lên tàu lớn ngay tại cửa nhà, không phải vòng sang cảng nước khác để chuyển tàu.'}, {'k': '3d', 'set': 'vanphong', 'light': 'day', 'cam': {'from': [[0.9, 1.5, 4.4], [0.3, 1.3, -1.0], 44], 'to': [[0.6, 1.45, 3.4], [0.2, 1.35, -1.2], 39]}, 'label': 'VÌ SAO ĐI THẲNG LẠI QUAN TRỌNG?', 'cast': [{'a': 'huy', 'p': [-0.7, 0, 0.5], 'act': 'chitay', 'side': -1, 'expr': 'smile'}, {'a': 'trang', 'p': [0.9, 0, 0.7], 'act': 'noi', 'side': -1, 'expr': 'worried'}], 'cap': ('BỚT MỘT LẦN CHUYỂN TÀU', 'LÀ BỚT CHỜ, BỚT PHÍ'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Trang Trâu hỏi em: đi thẳng hay chuyển tàu thì khác gì nhau, miễn hàng tới nơi là được? Em trả lời: mỗi lần chuyển tàu ở cảng khác là thêm một lần bốc xếp, thêm ngày chờ, thêm phí, và thêm rủi ro lỡ chuyến. Với lô cà phê, đồ gỗ hay quần áo đi Mỹ, vài ngày chậm có khi là mất đơn hàng sau.'}, {'k': 'bignum', 'anh': 'ov:container ship||container port aerial', 'cap': ('NĂM NGOÁI: HƠN 12,4 TRIỆU TEU', 'TĂNG 12,91%'), 'cols': ((255, 255, 255), (255, 196, 0)), 'value': 12.4, 'fmt': '{:,.1f}', 'unit': ' TRIỆU TEU', 'top': 'CONTAINER QUA CÁI MÉP – THỊ VẢI NĂM 2025', 'sub': 'Cảng vụ TP.HCM – Báo Xây dựng 11/1/2026', 'col': (255, 196, 0), 'say': 'Kết quả nằm trong con số. Theo Cảng vụ Hàng hải Thành phố Hồ Chí Minh, năm ngoái cụm cảng Cái Mép, Thị Vải đón hơn mười hai phẩy bốn triệu TEU container, tăng gần mười ba phần trăm.'}, {'k': 'noti', 'cap': ('HAI KỲ LIỀN THỨ 7', 'KỲ 2024 TRÊN SINGAPORE'), 'cols': ((255, 255, 255), (255, 196, 0)), 'noti': {'gio': '08:30', 'ngay': 'Bảng xếp hạng CPPI', 'items': [('Tin tức', 'Gemadept · 12/6/2024', 'World Bank: Cái Mép thứ 7 trong các cảng container hiệu quả nhất thế giới (CPPI 2023)', (255, 196, 0)), ('Tin tức', 'SGGP · 22/10/2025', 'CPPI 2024: Cái Mép giữ vị trí thứ 7, trên Singapore, Hồng Kông', (34, 197, 94))]}, 'say': 'Ngân hàng Thế giới có một chỉ số đo hiệu quả cảng container. Hai kỳ liền, chỉ số này xếp Cái Mép thứ bảy thế giới. Kỳ gần nhất, Cái Mép đứng trên cả Singapore và Hồng Kông, hai nơi mà trước đây hàng Việt phải đi nhờ.'}, {'k': 'noti', 'ch': 'Chương 3 – Từ hạng 7 xuống hạng 11', 'cap': ('TỪ HẠNG 7', 'XUỐNG HẠNG 11'), 'cols': ((255, 255, 255), (239, 68, 68)), 'noti': {'gio': '21:40', 'ngay': 'Thứ Năm 11/6/2026', 'items': [('Tin tức', 'bbw.vn · 11/6/2026', 'CPPI mới: Cái Mép 122 điểm, xếp thứ 11, giảm 10 điểm, lùi 4 bậc', (239, 68, 68)), ('Tin tức', 'bbw.vn · 11/6/2026', 'Hải Phòng lần đầu vào top 20, xếp thứ 13', (34, 197, 94))]}, 'say': 'Nhưng câu chuyện không dừng ở đó. Tháng sáu năm nay, bảng xếp hạng mới được công bố. Cái Mép giảm mười điểm, lùi bốn bậc, xuống thứ mười một. Cùng lúc, Hải Phòng tăng từ tám mươi bảy lên một trăm hai mươi hai điểm, lần đầu vào top hai mươi, xếp thứ mười ba.'}, {'k': 'map', 'cap': ('CÁI MÉP LÙI 4 BẬC', 'HẢI PHÒNG VÀO TOP 20'), 'cols': ((255, 255, 255), (255, 196, 0)), 'map': {'kf': [(15.3, 107.6, 5.9, 0.0), (15.3, 107.6, 6.1, 1.0)], 'nhan': [(10.535, 107.03, 'Cái Mép: thứ 7 xuống thứ 11', 0.05, 'cang'), (20.84, 106.69, 'Hải Phòng: thứ 13', 0.3, 'cang'), (16.5, 112.0, 'QĐ. Hoàng Sa (Việt Nam)', 0.05, 'chu'), (8.6, 114.5, 'QĐ. Trường Sa (Việt Nam)', 0.05, 'chu')], 'dim': 0.15}, 'say': 'Hai cảng biển lớn nhất hai đầu đất nước cùng nằm trong nhóm tốt nhất thế giới là tin vui. Nhưng vì sao Cái Mép tụt hạng, khi lượng hàng vẫn tăng?'}, {'k': 'bignum', 'anh': 'ov:container ship||container port aerial', 'cap': ('RIÊNG TÀU MẸ 9 THÁNG 2025', 'TĂNG 18%'), 'cols': ((255, 255, 255), (255, 196, 0)), 'value': 5.6, 'fmt': '{:,.1f}', 'unit': ' TRIỆU TEU', 'top': 'HÀNG QUA TÀU MẸ Ở CÁI MÉP – THỊ VẢI', 'sub': '9 tháng 2025, +18% – Báo SGGP 22/10/2025', 'col': (255, 196, 0), 'say': 'Lượng hàng thì vẫn đổ về. Chỉ riêng hàng đi tàu mẹ, chín tháng năm ngoái đạt năm phẩy sáu triệu TEU, tăng mười tám phần trăm. Em nghĩ cầu bến khó xây kịp với tốc độ tăng như thế.'}, {'k': 'giay', 'cap': ('GẦN NHƯ HẾT CÔNG SUẤT', 'TÀU TRỄ LỊCH CHỜ TỚI 3 NGÀY'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'giay': {'tieu_de': 'BÀI TOÁN CÔNG SUẤT CÁI MÉP – THỊ VẢI', 'so': 'Báo Xây dựng 11/1/2026', 'dau': 'ĐIỂM NGHẼN', 'dieu': [('Các cảng lớn gần đạt công suất thiết kế', 'GẦN HẾT CHỖ'), ('Tàu trễ lịch phải chờ cầu bến', '3 GIỜ – 3 NGÀY'), ('Hàng gom, rút bằng đường thủy', '75 – 80%'), ('Cảng có cầu riêng cho sà lan', 'CHỈ 2 CẢNG')]}, 'say': 'Em nghĩ câu trả lời nằm ở chữ đông. Theo báo Xây dựng, cụm cảng gần như hết công suất. Tàu đến trễ lịch phải chờ cầu bến từ ba giờ đến ba ngày. Phần lớn hàng được gom về bằng sà lan, nhưng chỉ hai cảng có cầu riêng cho sà lan. Không có cầu riêng, sà lan phải xếp hàng chung với tàu lớn, một chỗ tắc là kéo theo cả cụm.'}, {'k': '3d', 'set': 'phongkhach', 'light': 'day', 'cam': {'from': [[1.0, 1.3, 2.6], [1.0, 0.9, -1.8], 38], 'to': [[1.0, 1.25, 2.0], [1.0, 0.9, -1.8], 33]}, 'label': 'TỐI ĐÓ · NHÀ HÙNG XA LỘ', 'cast': [{'a': 'hung', 'p': [0.35, 0, -1.85], 'act': 'noi', 'ngoi': True, 'expr': 'worried'}, {'a': 'cuong', 'p': [1.65, 0, -1.85], 'act': 'dienthoai', 'ngoi': True, 'expr': 'stern'}], 'cap': ('"XE CHỜ CẢ NGÀY', 'THÌ AI TRẢ TIỀN?"'), 'cols': ((255, 255, 255), (239, 68, 68)), 'say': 'Tối đó Cường ghé nhà Hùng. Hùng kể: hôm nào tàu trễ, xe anh nằm chờ ở cảng cả ngày, mà tiền chuyến thì vẫn thế. Cường hỏi lại: vậy cảng đông như thế, sao không làm thêm đường cho xe chạy? Hùng chỉ ra cửa sổ: đang làm đấy, nhưng chưa xong. Cái giá của một cảng quá đông không nằm trên bảng xếp hạng. Nó nằm trong tiền dầu xe chạy không, trong ngày công tài xế ngồi chờ, và trong lô hàng của chủ xưởng lỡ chuyến tàu tuần này.'}, {'k': 'map', 'cap': ('ĐƯỜNG 991B: 9 KM, GẦN 4.000 TỶ', 'DỰ KIẾN THÔNG XE THÁNG 12/2026'), 'cols': ((255, 255, 255), (255, 196, 0)), 'map': {'kf': [(10.57, 107.07, 10.6, 0.0), (10.56, 107.06, 11.2, 1.0)], 'nhan': [(10.535, 107.03, 'Cụm cảng Cái Mép – Thị Vải', 0.05, 'cang'), (10.6, 107.12, 'Hướng Quốc lộ 51', 0.3), (10.43, 107.0, 'Luồng ra biển', 0.45, 'chu')]}, 'say': 'Theo báo Người Quan Sát, đường chín trăm chín mươi mốt B nối cụm cảng ra Quốc lộ năm mươi mốt dài khoảng chín km, bốn làn xe, vốn gần bốn nghìn tỷ đồng. Đường dự kiến thông xe toàn tuyến trong tháng mười hai này. Nhưng đường này vẫn cách cao tốc Biên Hòa, Vũng Tàu hơn tám km.'}, {'k': 'cards', 'anh': 'ov:container ship||container port aerial', 'cap': ('ĐIỀU GÌ TẠO NÊN', 'SỰ KHÁC BIỆT?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('Nước sâu', 'Tự nhiên cho sẵn', 'Sông Thị Vải gần biển'), ('Đào luồng', 'Ngân sách hơn 1.414 tỷ', 'Sâu 15,5 mét'), ('Doanh nghiệp', 'Xây cảng, mở tuyến', '22 tuyến đi Mỹ')], 'say': 'Vậy điều gì tạo nên sự khác biệt? Em nghĩ có ba lớp. Lớp một là nước sâu, tự nhiên cho sẵn. Lớp hai là đào luồng, nhà nước bỏ tiền. Lớp ba là doanh nghiệp dám xây cảng giữa rừng đước và kéo các hãng tàu lớn về. Thiếu lớp nào, tàu mẹ cũng không ghé. Và muốn giữ hạng, cả ba lớp phải chạy cùng tốc độ với lượng hàng.'}, {'k': 'hook', 'ch': 'Chương 4 – Doanh nghiệp sống nhờ câu chuyện cảng', 'cap': ('GIÁ CỔ PHIẾU GMD', 'PHẢN ỨNG VỚI TIN CẢNG'), 'cols': ((255, 255, 255), (255, 196, 0)), 'label': 'GMD – Gemadept (cảng Gemalink), giá điều chỉnh', 'chart': {'sym': 'GMDW', 'weeks': 108, 'mas': [(20, (255, 196, 0))], 'circles': [[19, 38.62, '13/3/2025: đón tàu 16.828 TEU', 2.0], [23, 26.46, '4/2025: Mỹ công bố thuế đối ứng', 4.5], [83, 50.67, '6/2026: CPPI tụt hạng 11', 7.0]]}, 'say': 'Một doanh nghiệp sống nhờ câu chuyện này là Gemadept, mã GMD, doanh nghiệp đứng sau cảng Gemalink ở Cái Mép. Biểu đồ nến tuần hai năm qua, giá đã điều chỉnh. Tuần đón tàu mười sáu nghìn tám trăm hai mươi tám container, giá không tăng. Đầu tháng tư năm ngoái, khi Mỹ công bố thuế đối ứng, giá giảm mạnh. Với doanh nghiệp có nhiều hàng đi Mỹ, thuế Mỹ là một rủi ro. Tháng sáu năm nay, tin tụt hạng không làm giá đổi chiều.'}, {'k': 'hook', 'cap': ('TIN TỐT CHƯA CHẮC LÊN GIÁ', 'TIN XẤU CHƯA CHẮC XUỐNG'), 'cols': ((255, 255, 255), (255, 196, 0)), 'label': 'GMD – 26 tuần gần nhất, giá điều chỉnh', 'chart': {'sym': 'GMDW', 'weeks': 26, 'mas': [(10, (56, 189, 248))], 'hlines': [[51.9, 'Tuần 23/11/2026: 51,9', (255, 196, 0), 1.5]], 'circles': [[23, 55.0, 'Tuần 9/11: 55,0', 3.0]]}, 'say': 'Hai mươi sáu tuần gần nhất, giá dao động từ khoảng bốn mươi lăm nghìn đồng đến năm mươi tám nghìn đồng một cổ phiếu. Bài học em rút ra: giá cổ phiếu phản ứng với cả thế giới, không chỉ với tin cảng. Em không nói nên mua hay bán, chỉ muốn anh chị thấy: câu chuyện hay và giá cổ phiếu là hai việc khác nhau.'}, {'k': 'checklist', 'cap': ('3 ĐIỀU NÊN THEO DÕI', 'Ở CÁI MÉP NĂM 2027'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'items': [('Đường 991B có thông xe đúng tháng 12?', (255, 196, 0)), ('Cảng nào mở thêm cầu bến cho sà lan?', (255, 196, 0)), ('Số tuyến đi Mỹ có còn tăng?', (239, 68, 68))], 'say': 'Nếu anh chị muốn tự theo dõi câu chuyện này, em gợi ý ba điều. Một, đường chín trăm chín mươi mốt B có thông xe đúng hẹn không. Hai, cảng nào mở thêm cầu bến, nhất là cầu cho sà lan. Ba, số tuyến đi Mỹ có còn tăng khi thuế quan thay đổi. Bảng giá và báo cáo tài chính các doanh nghiệp cảng em để miễn phí trên web chứng khoán Huy Nguyễn chấm com.'}, {'k': '3d', 'ch': 'Kết', 'set': 'cafevh', 'light': 'day', 'cam': {'from': [[-27.4, 1.5, 2.3], [-27.7, 0.8, 5.2], 42], 'to': [[-27.6, 1.42, 3.0], [-27.7, 0.8, 5.2], 38]}, 'label': 'SÁNG HÔM SAU · QUÁN NƯỚC GẦN CẢNG', 'cast': [{'a': 'hung', 'p': [-27.15, 0.15, 5.2], 'act': 'noi', 'ngoi': True, 'expr': 'smile'}, {'a': 'cuong', 'p': [-28.25, 0.15, 5.2], 'act': 'dienthoai', 'ngoi': True, 'expr': 'relief'}], 'cap': ('"HÓA RA KHÔNG PHẢI', 'CỨ THÀNH PHỐ LỚN"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Sáng hôm sau, Cường đọc lại bảng xếp hạng rồi nói: hóa ra cảng lớn không cần nằm trong thành phố lớn, mà cần nước sâu, cần người dám đào, và cần đường cho xe chạy. Hùng cười: còn đường thì để anh chờ thêm vài tuần nữa. Em nghĩ câu chuyện Cái Mép giống một bài học đầu tư: lợi thế tự nhiên chỉ là điểm xuất phát, thứ giữ được vị trí là đầu tư đều đặn và đúng chỗ nghẽn.'}, {'k': 'end', 'cap': ('CÁI MÉP SẼ LẤY LẠI', 'HẠNG 7 HAY KHÔNG?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Còn anh chị đặt cửa ai: sau khi đường chín trăm chín mươi mốt B thông xe, Cái Mép lấy lại hạng bảy thế giới, hay Hải Phòng vượt lên trong năm tới? Anh chị gõ Nam hoặc Bắc ở phần bình luận, kèm lý do nhé. Tập sau, em kể tiếp vì sao một vùng đất khác của Việt Nam thay đổi cả nền kinh tế.'}]
META = {'CH0612CM': {'kenh': '@chungkhoanhuynguyen', 'seri': 'Vì sao… (bản đồ)', 'ngay': '2026-12-06', 'gio_goi_y': '12:00', 'gio': '12:00', 'nhac': 'lofi', 'can_duyet': 'anh Huy duyệt trước khi hẹn', 'tieu_de': 'Từ Hạng 7 Xuống 11: Vì Sao Cảng Giữa Rừng Đước Tụt Hạng?', 'title': 'Từ Hạng 7 Xuống 11: Vì Sao Cảng Giữa Rừng Đước Tụt Hạng?', 'mo_ta': 'Vì sao cụm cảng Cái Mép – Thị Vải, nằm giữa rừng ngập mặn, đón được tàu mẹ 166.000 tấn đi thẳng Mỹ, châu Âu và hai kỳ liền đứng thứ 7 thế giới về hiệu quả? Và vì sao năm nay tụt xuống thứ 11? Kể bằng bản đồ vệ tinh, số liệu thật và câu chuyện tài xế container Hùng Xa Lộ.\n\nNguồn số liệu:\n• Luồng Cái Mép – Thị Vải sâu 15,5 m, tàu 160.000–200.000 tấn không phụ thuộc thủy triều, vốn ngân sách hơn 1.414 tỷ – Báo SGGP 9/2/2024\n• Tàu OOCL Bauhinia 166.000 tấn, 16.828 TEU, dài 366,99 m cập Tân Cảng Cái Mép – Thị Vải 13/3/2025 – Báo Hà Nội Mới\n• CPPI 2023 thứ 7 – Gemadept 12/6/2024; CPPI 2024 giữ thứ 7 – SGGP 22/10/2025; CPPI 2025: thứ 11 (122 điểm, −10), Hải Phòng thứ 13 – bbw.vn 11/6/2026\n• Năm 2025: hơn 12,4 triệu TEU (+12,91%); gần hết công suất; tàu chờ cầu 3 giờ – 3 ngày; 75–80% hàng gom bằng đường thủy – Báo Xây dựng 11/1/2026 (Cảng vụ TP.HCM)\n• 22 tuyến đi Mỹ, 2 tuyến châu Âu, 10 tuyến nội Á; đường 991B ~9 km, gần 4.000 tỷ, dự kiến thông xe 12/2026 – Người Quan Sát 1/11/2026\n• Số tự tính: 16.828 TEU × 6,1 m ≈ 102 km; 15,5 m ÷ 3,1 m/tầng ≈ 5 tầng nhà\n• Giá GMD: nến tuần, giá điều chỉnh – dữ liệu chungkhoanhuynguyen.com\n• Ảnh vệ tinh: Sentinel-2 cloudless – s2maps.eu by EOX IT Services GmbH (CC BY 4.0, dữ liệu Copernicus Sentinel 2016)\n\nBảng giá, báo cáo tài chính doanh nghiệp cảng biển: https://chungkhoanhuynguyen.com\nCần trao đổi riêng: Zalo 0365.188.286\n\nNhân vật Hùng Xa Lộ, Cường Sociu, Trang Trâu là hư cấu; số liệu là thật.', 'tags': ['Cái Mép', 'cảng Cái Mép Thị Vải', 'cảng biển Việt Nam', 'tàu mẹ', 'logistics', 'CPPI', 'Gemalink', 'GMD', 'kinh tế Việt Nam', 'vì sao'], 'bia_hook': ['TỪNG TRÊN SINGAPORE', 'GIỜ TỤT 4 BẬC?'], 'badge': 'TÀU 16.828 CONTAINER', 'bia_anh': 'ov:container ship||container port aerial', 'bia_hook_b': ['TÀU 367 MÉT', 'VÀO TẬN RỪNG ĐƯỚC'], 'badge_b': 'CẢNG CÁI MÉP', 'bia_hook_c': ['22 TUYẾN', 'ĐI MỸ TỪ ĐÂY'], 'badge_c': 'CẢNG CÁI MÉP', 'reel_hook': 'CẢNG GIỮA RỪNG ĐƯỚC|XẾP TRÊN CẢ SINGAPORE???', 'fb_post': 'Vì sao một cụm cảng giữa rừng đước lại đón tàu 16.828 container và hai kỳ liền xếp thứ 7 thế giới, kỳ gần nhất trên cả Singapore? 🚢\n\n👉 Luồng sâu 15,5 m – bằng 5 tầng nhà\n👉 22 tuyến tàu đi Mỹ\n👉 Nhưng năm nay tụt xuống thứ 11, khi tàu trễ lịch phải chờ cầu tới 3 ngày\n\nĐường 991B thông xe tháng 12 – Cái Mép có lấy lại hạng 7?\n🎬 Xem đầy đủ: {LINK}', 'chuong': ['Mở đầu', 'Chương 1 – Cảng lớn không nằm trong thành phố', 'Chương 2 – Con tàu dài gần bằng Landmark 81', 'Chương 3 – Từ hạng 7 xuống hạng 11', 'Chương 4 – Doanh nghiệp sống nhờ câu chuyện cảng', 'Kết']}}
